/*
 * dsh-plugin-mascot — configuration console.
 *
 * The page runs no server and touches nothing on the machine viewing it. It turns
 * choices into a YAML string, and — in the live preview — reads the artwork the
 * visitor already installed on their own DSH, in order to animate it here. That
 * read is the only thing this page ever asks of the host, and it goes through the
 * plugin's own allowlisted art route.
 *
 * The look catalogue comes from `site/catalog.json` and the skeleton from
 * `site/rig.js`, both generated by `scripts/build-site.mjs` from the plugin's own
 * sources, so neither can drift from what the plugin actually does.
 */

import { createPreview } from "./preview.js";

const REPO = "https://github.com/ZYAONS/dsh-plugin-mascot";
/** 语言存在自己的键里，与角色、主题那些选择互不干扰。 */
const LANG_KEY = "dsh.mascot.console.language";

const STATE_KEY = "dsh-mascot-console";


/** Which per-character interface style each theme maps to, for the card art. */
const THEME_COLOURS = {
  rhodes: { accent: "#37e0d8", label: "CONSOLE", page: "closure" },
  mewtype: { accent: "#ff4d9d", label: "LIVE SET", page: "yuno" },
  rhine: { accent: "#a3dd7a", label: "RHINE LAB", page: "muelsyse" },
  sakiko: { accent: "#8b7cf8", label: "AVE MUJICA", page: "sakiko" },
  miuyin: { accent: "#3fa9f5", label: "OPERATOR", page: "miuyin" },
  yuyuan: { accent: "#4fd6e8", label: "OPERATOR", page: "yuyuan" },
  dusk: { accent: "#5b6fd8", label: "SUI", page: "dusk" },
  makoto: { accent: "#2f6fe0", label: "P3R", page: "makoto" },
};

/** Human names for the page themes, for the header readout. */
const PAGE_THEME_NAMES = {
  auto: "中性银",
  closure: "银上之蓝",
  yuno: "霓虹粉",
  muelsyse: "莱茵绿",
  sakiko: "紫蓝舞台",
  miuyin: "晴空蓝",
  yuyuan: "水蓝",
  dusk: "水墨",
  makoto: "P3R 蓝",
};

const state = {
  catalog: { characters: [], looks: [], version: "0.0.0", repository: REPO },
  plugin: true,
  character: "closure",
  /** Look ids the visitor turned off, per character. */
  off: new Set(),
  skeleton: true,
  animated: true,
  balance: true,
  mount: "name",
  dir: "",


  /**
   * Whether the visitor chose the neutral theme.
   *
   * `auto` is the silver that belongs to no character, and it is the default. Every
   * other theme is the selected character's own, which is why it is derived on each
   * render rather than stored: choosing a character's theme also selects that
   * character, so the two can be set from the header or from section 02 and can
   * never end up describing different people.
   */
  autoTheme: true,
  /** The theme last applied; a read-out, written by `applyTheme`. */
  theme: "auto",
  /**
   * The look the frame is showing, when the visitor picked one by clicking a card.
   * Distinct from the allowlist ticks: the ticks decide what the *plugin* may offer,
   * this decides what you are looking at.
   */
  previewLook: undefined,
  /**
   * Set when a link named the look. A deep link is an instruction, not a preference,
   * so it is honoured even for a look the visitor has unticked — otherwise the page
   * silently shows a different one and the link appears not to work.
   */
  previewLookPinned: false,
  /** Set by `?preview=test`; renders the rig test pattern instead of a host. */
  previewTest: false,
};

const $ = (id) => document.getElementById(id);

/** Escape the two characters that could break out of the YAML snippet. */
const yamlString = (value) => `'${String(value).replace(/'/gu, "''")}'`;

/** Look up one character record. */
const characterOf = (id) => state.catalog.characters.find((entry) => entry.id === id);

/** The looks of one character, in declaration order. */
const looksOf = (id) => state.catalog.looks.filter((look) => look.character === id);

/**
 * The look the frame is showing: the one the visitor chose, or the first the plugin
 * would offer. Resolved against what is enabled, so unticking the look on screen
 * moves the frame on rather than leaving it showing something the plugin will not.
 */
function previewedLook() {
  const all = looksOf(state.character);
  if (state.previewLookPinned && all.some((look) => look.id === state.previewLook)) return state.previewLook;
  const available = enabledLooks(state.character);
  return available.some((look) => look.id === state.previewLook) ? state.previewLook : available[0]?.id;
}

/** Whether a look is currently enabled. */
const lookOn = (id) => !state.off.has(id);

/** The looks that survive the visitor's choices; a look is only dropped when every
 * option of a character was switched off, in which case that character keeps all
 * of them rather than becoming unusable. */
function enabledLooks(characterId) {
  const all = looksOf(characterId);
  const on = all.filter((look) => lookOn(look.id));
  return on.length > 0 ? on : all;
}

//#region render
/**
 * The page theme a character wears.
 *
 * Derived, never chosen. The theme and the artwork on screen are two statements
 * about the same character, so a control that let them disagree was a control that
 * let the page contradict itself — picking Yuno and getting Closure's blue, or the
 * reverse. There is no theme state to get out of step, because there is no theme
 * state: it is a function of the selection.
 */
function pageThemeOf(characterId) {
  const character = characterOf(characterId);
  // An unknown character falls back to the page's own neutral theme, not to one of
  // the other characters' — the fallback should not be a claim about who this is.
  return THEME_COLOURS[character?.theme]?.page ?? "auto";
}

/**
 * Choose a page theme.
 *
 * A character's theme also selects that character, so the header buttons and the
 * cards in section 02 are two ways of saying one thing and cannot disagree. `auto`
 * is the neutral silver: it belongs to no character, so it claims nothing and
 * leaves the selection alone.
 */
function chooseTheme(choice) {
  if (PAGE_THEME_NAMES[choice] === undefined) return;
  state.autoTheme = choice === "auto";
  if (choice !== "auto") {
    const character = state.catalog.characters.find((entry) => THEME_COLOURS[entry.theme]?.page === choice);
    if (character !== undefined) {
      state.character = character.id;
      // A look belongs to one character, so a choice made for the last one is not a
      // choice about this one.
      state.previewLook = undefined;
      state.previewLookPinned = false;
      renderCharacters();
      renderLooks();
    }
  }
  render();
}

/** Apply the theme, and light the control that set it. */
function applyTheme() {
  const theme = state.autoTheme ? "auto" : pageThemeOf(state.character);
  state.theme = theme;
  for (const button of $("theme").querySelectorAll("button")) {
    button.dataset.on = button.dataset.themeChoice === theme ? "1" : "0";
  }
  document.documentElement.dataset.theme = theme;
  $("m-theme").textContent = PAGE_THEME_NAMES[theme] ?? theme;
  // The name already carries whatever identifies it — the character where there is one,
  // the colour where there is not — so it is used as written rather than prefixed with
  // the character again, which is how it came to read "Muelsyse · Muelsyse · light green".
  // Read once, before anything uses it: the declaration used to sit below this point,
  // and reading it here first threw a ReferenceError from inside the first render.
  const character = characterOf(state.character);
  // 角色名在前、主题名在后，两者都用中文名 —— 中文界面里出现英文角色名就是把
  // 名称留给了机器翻译去猜。
  const named = character?.name ?? character?.nameEn ?? state.character;
  $("theme-name").textContent = state.autoTheme === true
    ? (PAGE_THEME_NAMES[theme] ?? theme)
    : `${named} · ${PAGE_THEME_NAMES[theme] ?? theme}`;
  $("theme-swatch").style.background = getComputedStyle(document.documentElement).getPropertyValue("--signal").trim();
}

/** Persist the console state so a reload keeps the visitor's choices. */
function save() {
  try {
    window.localStorage.setItem(STATE_KEY, JSON.stringify({
      plugin: state.plugin,
      character: state.character,
      off: [...state.off],
      skeleton: state.skeleton,
      animated: state.animated,
      balance: state.balance,
      mount: state.mount,
      dir: state.dir,
      autoTheme: state.autoTheme,

    }));
  } catch {
    /* private mode — the choices simply do not persist */
  }
}

/** Restore a previous session, tolerating anything unreadable. */
function load() {
  try {
    const raw = window.localStorage.getItem(STATE_KEY);
    if (raw === null) return;
    const saved = JSON.parse(raw);
    if (typeof saved.plugin === "boolean") state.plugin = saved.plugin;
    if (typeof saved.character === "string") state.character = saved.character;
    if (Array.isArray(saved.off)) state.off = new Set(saved.off);
    if (typeof saved.skeleton === "boolean") state.skeleton = saved.skeleton;
    if (typeof saved.animated === "boolean") state.animated = saved.animated;
    if (typeof saved.balance === "boolean") state.balance = saved.balance;
    if (saved.mount === "name" || saved.mount === "file") state.mount = saved.mount;
    if (typeof saved.dir === "string") state.dir = saved.dir;
    if (typeof saved.autoTheme === "boolean") state.autoTheme = saved.autoTheme;

  } catch {
    /* unreadable state is not worth reporting; defaults are fine */
  }
}

/** A Windows or POSIX path as a file: URL, which is what a patch row wants. */
function fileUrl(path) {
  const trimmed = String(path).trim().replace(/[\\/]+$/u, "");
  if (trimmed === "") return "";
  if (/^file:/iu.test(trimmed)) return trimmed;
  if (/^[a-z]:[\\/]/iu.test(trimmed)) return `file:///${trimmed.replace(/\\/gu, "/")}`;
  return `file://${trimmed.startsWith("/") ? "" : "/"}${trimmed}`;
}

/** Render the character cards. */
function renderCharacters() {
  const host = $("characters");
  host.textContent = "";
  for (const character of state.catalog.characters) {
    const theme = THEME_COLOURS[character.theme] ?? { accent: "#ffd400", label: "—" };
    const card = document.createElement("div");
    card.className = "card";
    card.dataset.on = character.id === state.character ? "1" : "0";
    card.tabIndex = 0;
    card.innerHTML = [
      `<span class="check"></span>`,
      `<div class="code">${theme.label} / ${character.id}</div>`,
      `<div class="name">${character.name ?? character.nameEn}</div>`,
      `<div class="latin">${character.latin}</div>`,
      `<div class="role">${character.roleEn ?? character.role}<br>${character.taglineEn ?? character.tagline ?? ""}</div>`,
      `<div class="swatch" style="background:${theme.accent}"></div>`,
    ].join("");
    const choose = () => {
      state.character = character.id;
      // The pin belongs to the character that was pinned: keeping it would hold the
      // frame on a look the new character does not have.
      state.previewLookPinned = false;
      // The card and the header button say the same thing, so both move together.
      state.autoTheme = false;
      // A look belongs to one character, so a choice made for the last one is not a
      // choice about this one.
      state.previewLook = undefined;
      // And the theme follows the character, unless the visitor has asked for the
      // neutral one — which describes no character and so cannot contradict this.
      if (state.theme !== "auto") state.theme = pageThemeOf(character.id);
      renderCharacters();
      renderLooks();
      render();
    };
    card.addEventListener("click", choose);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        choose();
      }
    });
    host.append(card);
  }
}

/** Render the look checkboxes for the selected character. */
function renderLooks() {
  const host = $("looks");
  host.textContent = "";
  for (const look of looksOf(state.character)) {
    const card = document.createElement("div");
    card.className = "card";
    card.dataset.on = lookOn(look.id) ? "1" : "0";
    card.dataset.preview = look.id === previewedLook() ? "1" : "0";
    card.tabIndex = 0;
    card.innerHTML = [
      `<span class="check"></span>`,
      `<div class="code">${look.id}</div>`,
      `<div class="name">${look.name ?? look.nameEn}</div>`,
      look.animated ? `<span class="badge">Multi-frame</span>` : "",
    ].join("");
    // One click does both, because both are what the visitor means by it: tick the
    // look into the plugin's allowlist, and put it in the frame so they can see the
    // thing they just picked.
    const toggle = () => {
      if (lookOn(look.id)) state.off.add(look.id);
      else state.off.delete(look.id);
      state.previewLook = look.id;
      // Pinned, so the frame keeps showing what was just clicked even if the same click
      // unticked it. Without this the card appears to do nothing at all.
      state.previewLookPinned = true;
      renderLooks();
      render();
    };
    card.addEventListener("click", toggle);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        toggle();
      }
    });
    host.append(card);
  }
}

/** Paint one toggle element from the state. */
function paintToggle(id, on) {
  const node = $(id);
  node.dataset.on = on ? "1" : "0";
  node.setAttribute("aria-checked", on ? "true" : "false");
}

/** The YAML the visitor pastes into their profile. */
function buildConfig() {
  const character = characterOf(state.character);
  const looks = enabledLooks(state.character).map((look) => look.id);
  const lines = [];

  if (!state.plugin) {
    lines.push("# 看板娘插件：已关闭 —— 不插入这一行就是关闭状态。");
    lines.push("# 想重新打开，把下面这段前面的 # 去掉。");
    lines.push("#");
    lines.push("# - insert:");
    lines.push("#     - id: mascot");
    lines.push(`#       name: ${state.mount === "file" ? "file:///…/dsh-plugin-mascot/lib/index.js" : "dsh-plugin-mascot"}`);
    return lines.join("\n");
  }

  lines.push("# DSH profile patch —— 贴进 ~/.dsh/profiles/desktop/cordis.patch.yml");
  lines.push("# 不要写 cordis.yml：它每次启动都会被改写成 []。");
  lines.push("- insert:");
  lines.push("    - id: mascot");
  if (state.mount === "file") {
    const resolved = fileUrl(state.dir);
    lines.push("      # Mounted by absolute path: the plugin has no runtime dependencies,");
    lines.push("      # so it does not need to be installed into the profile.");
    lines.push(`      name: ${yamlString(resolved === "" ? "file:///path/to/dsh-plugin-mascot/lib/index.js" : `${resolved}/lib/index.js`)}`);
  } else {
    lines.push("      name: dsh-plugin-mascot");
  }
  lines.push("      config:");
  lines.push(`        # 默认角色：${character === undefined ? state.character : (character.name ?? character.nameEn)}`);
  lines.push(`        character: ${state.character}`);
  const available = enabledLooks(state.character);
  const preferred = available.find((look) => (state.animated ? true : !look.animated)) ?? available[0];
  lines.push("        # Default look within that character. Empty means the plugin picks");
  lines.push("        # its first installed one, which is what this says before the");
  lines.push("        # catalogue has loaded.");
  lines.push(`        look: ${preferred === undefined ? '""' : preferred.id}`);
  lines.push("        # Allowlist of looks the panel may offer. An empty list means");
  lines.push("        # every installed look.");
  lines.push("        looks:");
  for (const id of looks) lines.push(`          - ${id}`);
  lines.push("        # Skeletal animation: three bones rigged from the silhouette, driving");
  lines.push("        # a skinned mesh. Falls back to a still image without WebGL2.");
  lines.push(`        skeleton: ${state.skeleton}`);
  lines.push("        # 面板里的账户余额；关闭后浏览器完全不查询。");
  lines.push(`        balance: ${state.balance}`);
  if (!state.animated) {
    lines.push("        # Multi-frame looks were switched off in the console, so only");
    lines.push("        # single-frame looks are allowlisted above.");
  }
  return lines.join("\n");
}

/** Re-render everything derived from state. */
function render() {
  paintToggle("t-plugin", state.plugin);
  paintToggle("t-balance", state.balance);
  paintToggle("t-skeleton", state.skeleton);
  paintToggle("t-animated", state.animated);
  $("s-plugin").className = state.plugin ? "status" : "status off";
  $("s-plugin").innerHTML = `<i></i>${state.plugin ? "已启用" : "已关闭"}`;
  $("dir-field").classList.toggle("hidden", state.mount !== "file");
  $("sec-look").classList.toggle("hidden", !state.plugin);
  $("sec-character").classList.toggle("hidden", !state.plugin);
  $("output").textContent = buildConfig();
  // Applied last, and on every render, because "auto" resolves against the
  // character and the character can change in the same pass.
  applyTheme();
  // The preview follows the selection: switching character switches what floats in
  // the frame, which is the point of having it here at all.
  paintCredit(state.character);
  // Offered only by the neutral theme: a character's theme is a statement about who is
  // on screen, and "or preview an image of your own" is a different statement.
  $("preview-tools").classList.toggle("hidden", !state.autoTheme);
  paintSiren();
  drivePreview();
  save();
}
//#endregion

