//#region preview
/**
 * Who owns the character on screen.
 *
 * Shown next to the artwork rather than only in the footer: the console displays
 * someone else's character, and the credit belongs where the reader is looking.
 * See COPYRIGHT.md — this project ships no artwork and claims no rights in it.
 */
const CREDITS = {
  closure: { work: "明日方舟（Arknights）", owner: "鹰角网络 Hypergryph" },
  yuno: { work: "BanG Dream! ／ 梦限大 MewType", owner: "Bushiroad" },
  muelsyse: { work: "明日方舟（Arknights）", owner: "鹰角网络 Hypergryph" },
  sakiko: { work: "BanG Dream! Ave Mujica", owner: "Bushiroad" },
  miuyin: { work: "明日方舟（Arknights）", owner: "鹰角网络 Hypergryph" },
  yuyuan: { work: "明日方舟（Arknights）", owner: "鹰角网络 Hypergryph" },
  dusk: { work: "明日方舟（Arknights）", owner: "鹰角网络 Hypergryph" },
  makoto: { work: "明日方舟 × 女神异闻录3 Reload", owner: "鹰角网络 Hypergryph / ATLUS" },
};

/** Paint the attribution for the selected character. */
function paintCredit(characterId) {
  const node = $("preview-credit");
  // The neutral theme draws the rig, not a character, so naming one would attribute
  // artwork that is not on screen.
  if (state.autoTheme === true) {
    node.textContent = "";
    return;
  }
  const credit = CREDITS[characterId];
  if (credit === undefined) {
    node.textContent = "";
    return;
  }
  const character = characterOf(characterId);
  node.innerHTML =
    `素材：<b>${character?.name ?? characterId}</b> © <b>${credit.owner}</b> —— ${credit.work}。` +
    `从原始出处加载，本项目不再分发。非官方同人作品，与权利人无隶属或背书关系。`;
}
/** The live preview, created on boot. A ref so `render` can reach it. */
const previewRef = { current: null };

/** Paint one preview status line. */
function paintPreviewStatus({ kind, message }) {
  const node = $("preview-status");
  node.textContent = message;
  node.dataset.kind = kind;
  const badge = $("s-preview");
  // `isLive` means the plugin answered on this origin; a supplied file counts too.
  const connected = previewRef.current?.isLive() === true || $("preview-host").querySelector("canvas, .preview-still") !== null;
  badge.className = connected ? "status" : "status off";
  badge.innerHTML = `<i></i>${connected ? "预览中" : "未连接"}`;
}

/** Create the preview and wire its controls. */
async function setupPreview() {
  const preview = createPreview($("preview-host"), paintPreviewStatus);
  preview.setCatalogue(state.catalog);
  previewRef.current = preview;

  // The skeleton needs no artwork at all, so it is the one control that always has
  // something to show — on either copy, for any look.
  $("preview-skeleton").addEventListener("click", async () => {
    // The neutral theme names no character, so its skeleton is a plain standing figure
    // rather than one of the roster's outlines — the theme has just declined to say who
    // is on screen, and drawing a specific silhouette would say it anyway.
    await preview.useSkeleton(state.character, previewedLook(), { generic: state.autoTheme });
    // The driver did not ask for this, so its record is stale: null it and the next
    // render re-decides instead of trusting a key that no longer describes the frame.
    previewShows = null;
    paintPreviewStatusRefresh();
  });
  $("preview-file").addEventListener("change", async (event) => {
    const file = event.target.files?.[0];
    if (file === undefined) return;
    await preview.useFile(file);
    previewShows = null;
    paintPreviewStatusRefresh();
  });

  // Which of the two lives this page is depends on where it is served from, and
  // that decides what the section can honestly offer.
  const mode = await preview.detect();
  if (mode === "local") {
    // 标记模式，而不是让断言去读句子：读句子的断言会在任何一次翻译后变成假失败。
    $("preview-note").dataset.mode = "local";
    $("preview-note").textContent = "这一份由插件自己托管，所以下框读的是这台机器上装好的素材。";
    await preview.show(state.character, previewedLook());
    const drawn = $("preview-host").querySelector("canvas, .preview-still") !== null;
    preview.report(drawn
      ? "来自本机：显示你装好的素材，由插件同一套骨架绑定驱动。"
      : "Connected to the plugin, but nothing could be drawn — see the note below.");
    return;
  }

  $("preview-note").innerHTML =
    ($("preview-note").dataset.mode = "published") &&
    "这一份是公网版本，素材来自 <code>art/looks.json</code> 里声明的源站。" +
    "不发 CORS 头的源站读不进 WebGL，只有发了头的那些才会被骨骼形变。" +
    "想全部动起来，跑 <code>npm run art:publish</code> 并提交 <code>docs/art/</code>。";

  // `?preview=test` drives the synthetic figure through the WebGL path. It is not a
  // control on the page — the page offers the skeleton, which is the useful thing —
  // but it is the only way to exercise measure -> auto-rig -> skin -> animate with
  // no artwork present at all, so the self-test still uses it.
  if (state.previewTest) {
    await preview.useTestPattern();
    paintPreviewStatusRefresh();
    return;
  }
  // Through the same driver the render pass uses, so the first frame and every later
  // one are chosen by one rule.
  drivePreview();
  paintPreviewStatusRefresh();
}

/**
 * What the frame should be showing, and whether it already is.
 *
 * The key matters: the preview starts an animation, and re-issuing the same request
 * on every render restarted it whenever an unrelated toggle was flipped. It also
 * makes the Auto rule a one-liner — the neutral theme belongs to no character, so it
 * shows the rig itself rather than borrowing someone's artwork, and switching to a
 * character's theme swaps the skeleton back out for the character.
 */
let previewShows = null;

/** Point the preview at the current selection, if it is not already there. */
function drivePreview() {
  const preview = previewRef.current;
  if (preview === null || preview === undefined) return;
  // A character's theme shows that character's artwork. A file the visitor chose, or
  // the skeleton, belongs to the neutral theme that offered the control — leaving one
  // in place here is the page contradicting the selection it is displaying. Clearing
  // it changes the frame, so the record below is no longer true either.
  if (!state.autoTheme && preview.clearOverride() === true) previewShows = null;
  const look = previewedLook();
  const key = [state.autoTheme ? "skeleton" : "art", state.character, look ?? ""].join("|");
  if (key === previewShows) return;
  previewShows = key;
  if (state.autoTheme) preview.useSkeleton(state.character, look, { generic: true }).catch(() => {});
  else preview.show(state.character, look).catch(() => {});
}

/** One audio element, reused: a second record stops the first. */
let sirenAudio;

/**
 * Show the selected character's Siren Records album, if it has one.
 *
 * The mapping is by the event the character came from — Siren releases by event, not by
 * character, so there is nothing to match on a name. Covers and audio are hotlinked from
 * the official CDN; the console only knows their cids.
 */
function paintSiren() {
  const node = $("preview-siren");
  const record = state.catalog.siren?.[state.character];
  if (record === undefined || record === null || record.cover == null) {
    node.dataset.on = "0";
    node.removeAttribute("href");
    return;
  }
  node.dataset.on = "1";
  $("siren-cover").src = record.cover;
  $("siren-cover").alt = record.album;
  $("siren-album").textContent = String(record.album).trim();
  $("siren-meta").textContent = `塞壬唱片-MSR · ${String(record.tracks)} 首 · ${record.event}`;
  node.href = "https://monster-siren.hypergryph.com/";
}

/** Play the record's first track, or stop it if it is already playing. */
function playSiren() {
  const node = $("preview-siren");
  const record = state.catalog.siren?.[state.character];
  const src = record?.track?.src;
  if (typeof src !== "string" || src === "") return;
  if (sirenAudio !== undefined) {
    sirenAudio.pause();
    sirenAudio = undefined;
    node.dataset.playing = "0";
    return;
  }
  sirenAudio = new Audio(src);
  // Same reason as the cover: the CDN refuses requests that carry a Referer.
  sirenAudio.referrerPolicy = "no-referrer";
  node.dataset.playing = "1";
  sirenAudio.addEventListener("ended", () => {
    node.dataset.playing = "0";
    sirenAudio = undefined;
  });
  sirenAudio.play().catch(() => {
    node.dataset.playing = "0";
    sirenAudio = undefined;
  });
}

/** Re-read the connection badge after a connect or file pick changed it. */
function paintPreviewStatusRefresh() {
  const node = $("preview-status");
  paintPreviewStatus({ kind: node.dataset.kind ?? "idle", message: node.textContent });
}
//#endregion

//#region events
/** Wire one toggle element to a state setter. */
function bindToggle(id, apply) {
  const node = $(id);
  const flip = () => {
    apply(!node.dataset.on || node.dataset.on !== "1");
    render();
  };
  node.addEventListener("click", flip);
  node.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      flip();
    }
  });
}

/** Copy text, preferring the async clipboard and falling back to a textarea. */
async function copyText(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.append(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    return ok;
  }
}

/** Save a string as a file, entirely client-side. */
function download(name, text) {
  const blob = new Blob([text], { type: "text/yaml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

/** Show a transient label on a button. */
function flash(button, label) {
  const original = button.textContent;
  button.textContent = label;
  button.disabled = true;
  window.setTimeout(() => {
    button.textContent = original;
    button.disabled = false;
  }, 1400);
}
//#endregion

/**
 * Read a deep link.
 *
 * `?theme=`, `?character=` and `?preview=` let a link point at a specific
 * configuration — "show me the Yuno version" is a URL — and `?preview=test` also
 * makes the whole chain testable without a host: a headless run of that link
 * exercises measure → auto-rig → skin → animate in the page itself.
 *
 * A query parameter outranks stored state, because a link that says what it wants
 * should not be silently overridden by a previous visit.
 */
function applyQuery() {
  let query;
  try {
    query = new URLSearchParams(window.location.search);
  } catch {
    return;
  }

  const character = query.get("character");
  if (character !== null && character !== "") {
    state.character = character;
    // Applied on the next render, once the catalogue can resolve the mapping.
    state.autoTheme = false;
  }
  const theme = query.get("theme");
  // `?theme=` moves the character too, through the same rule the buttons use.
  if (theme !== null && theme !== "" && PAGE_THEME_NAMES[theme] !== undefined) chooseTheme(theme);
  const look = query.get("look");
  if (look !== null && look !== "") {
    state.previewLook = look;
    state.previewLookPinned = true;
  }
  const preview = query.get("preview");
  if (preview === "test") state.previewTest = true;
}

/** Boot: fetch the catalogue, wire the controls, draw. */
async function main() {
  load();
  applyQuery();
  try {
    const response = await fetch("site/catalog.json", { cache: "no-cache" });
    if (response.ok) state.catalog = await response.json();
  } catch {
    /* the page still works, just with an empty catalogue */
  }
  // The preview was created before the catalogue arrived, so hand it over now that
  // it has: on the published copy the catalogue is where the preview finds both the
  // framing and the source URLs for every look.
  previewRef.current?.setCatalogue(state.catalog);

  // Reconcile the theme with the character, now that the catalogue can answer which
  // theme a character wears. This has to run *after* the fetch: before it, no character
  // is known, and a reconciliation would read that as "no theme" and discard the
  // visitor's stored choice. A stored character-theme can also disagree with the
  // character a link names — last visit's preference against a `?character=` — which is
  // precisely the mismatch the pairing rule exists to prevent.
  if (state.theme !== "auto") state.theme = pageThemeOf(state.character);

  const characters = state.catalog.characters ?? [];
  if (characters.length > 0 && !characters.some((entry) => entry.id === state.character)) {
    state.character = characters[0].id;
  }

  $("m-version").textContent = state.catalog.version ?? "—";
  $("m-characters").textContent = String(characters.length);
  $("m-looks").textContent = String((state.catalog.looks ?? []).length);
  $("f-repo").href = state.catalog.repository ?? REPO;
  $("f-readme").href = `${state.catalog.repository ?? REPO}#readme`;
  $("download-repo").href = `${state.catalog.repository ?? REPO}/archive/refs/heads/main.zip`;

  for (const button of $("lang").querySelectorAll("button")) {
    button.addEventListener("click", () => {
      applyLanguage(button.dataset.langChoice);
      render();
    });
  }
  applyLanguage(readStoredLanguage());

  // 试听：点按钮出声，点别处进官网 —— 所以按钮要吃掉点击，不让它冒泡到链接。
  $("siren-play").addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    playSiren();
  });

  bindToggle("t-plugin", (value) => { state.plugin = value; });
  bindToggle("t-balance", (value) => { state.balance = value; });
  bindToggle("t-skeleton", (value) => { state.skeleton = value; });
  bindToggle("t-animated", (value) => { state.animated = value; });



  for (const button of $("theme").querySelectorAll("button")) {
    button.addEventListener("click", () => {
      chooseTheme(button.dataset.themeChoice);
    });
  }

  for (const button of $("mount").querySelectorAll("button")) {
    button.addEventListener("click", () => {
      state.mount = button.dataset.mount;
      for (const peer of $("mount").querySelectorAll("button")) {
        peer.dataset.on = peer === button ? "1" : "0";
      }
      render();
    });
    button.dataset.on = button.dataset.mount === state.mount ? "1" : "0";
  }

  $("dir").addEventListener("input", (event) => {
    state.dir = event.target.value;
    render();
  });
  $("dir").value = state.dir;

  $("copy").addEventListener("click", async () => {
    const ok = await copyText(buildConfig());
    flash($("copy"), ok ? "已复制" : "复制失败");
  });
  $("download-config").addEventListener("click", () => {
    download("cordis.patch.yml", `${buildConfig()}\n`);
    flash($("download-config"), "已下载");
  });

  renderCharacters();
  renderLooks();
  render();
  // Started, not awaited, and after the first render: setting the preview up loads
  // artwork over the network, and the console must not wait on a decoration to become
  // usable. It fills in when it can, and drives itself from then on.
  setupPreview().catch(() => {
    /* a preview that cannot start leaves the console exactly as it is */
  });
}

main();
